        for i in range(self.dim):
            chaotic_term += np.sin(x[:, i] * np.pi * (i + 1)) * np.cos(x[:, i] * np.pi * (i + 1))

        # Combine all terms with different weights
        return 0.5 * center_distance + 0.3 * oscillation_term + 0.2 * chaotic_term + repulsion_term
